<?php

namespace App\Models;

use App\Support\Lookups;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/**
 * `counterparties` table of the MyAT database.
 * Generated by `php artisan app:generate-models`; add relationships below.
 *
 * @property int|null $CID
 * @property string|null $CounterShortName
 * @property string|null $DOY
 * @property string|null $LesseName
 * @property string|null $VAT
 * @property string|null $BankName
 * @property string|null $InvoiceType
 * @property string|null $PaymentType
 * @property string|null $BankAccount
 * @property string|null $IBAN
 * @property string|null $Notes
 * @property string|null $Phones
 * @property string|null $Email
 * @property string|null $Active
 * @property string|null $LastUpdatedBy
 * @property Carbon|null $LastUpdatedDate
 * @property string|null $CreatedBy
 * @property Carbon|null $CreatedDate
 * @property int|null $UserID
 * @property string|null $Address
 * @property int|null $oldid
 * @property int|null $IsSupplier
 * @property int|null $IsAssistant
 * @property int|null $IsCoach
 * @property string|null $ElorusID
 * @property string|null $MydataDocumentType
 * @property string|null $MydataClassCategory
 * @property string|null $MydataClassType
 * @property string|null $DocumentType
 * @property string|null $CoachName
 * @property string|null $SupplierName
 * @property string|null $AssistantNum
 * @property string|null $AssistantAMKA
 * @property string|null $AssistantName
 * @property int|null $LeadName
 * @property string|null $WCR
 * @property int|null $GetReview
 */
class Counterparty extends Model
{
    protected $table = 'counterparties';

    protected $primaryKey = 'CID';

    public $incrementing = true;

    protected $keyType = 'int';

    public $timestamps = false;

    protected $guarded = [];

    protected function casts(): array
    {
        return [
            'CID' => 'integer',
            'LastUpdatedDate' => 'datetime',
            'CreatedDate' => 'datetime',
            'UserID' => 'integer',
            'oldid' => 'integer',
            'IsSupplier' => 'integer',
            'IsAssistant' => 'integer',
            'IsCoach' => 'integer',
            'LeadName' => 'integer',
            'GetReview' => 'integer',
        ];
    }

    /** NOT NULL columns whose database default means "not set". */
    public const NOT_REGISTERED = ['ElorusID', 'MydataDocumentType', 'MydataClassCategory', 'MydataClassType', 'DocumentType', 'CoachName', 'SupplierName'];

    protected static function booted(): void
    {
        // PHPRunner's add/edit events.
        static::creating(function (Counterparty $c): void {
            $c->CreatedDate = now();
            $c->CreatedBy = auth()->user()?->username;
        });
        static::updating(function (Counterparty $c): void {
            $c->LastUpdatedDate = now();
            $c->LastUpdatedBy = auth()->user()?->username;
        });
        static::saving(function (Counterparty $c): void {
            foreach (self::NOT_REGISTERED as $column) {
                if ($c->isDirty($column) || ! $c->exists) {
                    if (blank($c->getAttribute($column))) {
                        $c->setAttribute($column, 'NotRegistered');
                    }
                }
            }
        });
        // Customers, coaches and guides feed the dropdowns everywhere.
        static::saved(fn () => Lookups::flush());
        static::deleted(fn () => Lookups::flush());
    }

    /** `Active` is text; PHPRunner's checkbox treats any non-empty value but 0/No as ticked. */
    public static function isActiveValue(mixed $value): bool
    {
        return ! in_array(strtolower(trim((string) $value)), ['', '0', 'no', 'off', 'false'], true);
    }

    public function files(): HasMany
    {
        return $this->hasMany(MyatPartnerFile::class, 'cid', 'CID');
    }
}
